// Raumschiff und schwebende Felsbrocken: Seifenblasen zerplatzen Felsbrocken, Beruehrung beendet die Runde.
export default {
  title: "Raumschiff und schwebende Felsbrocken",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { ship: { x: 160, y: 590, w: 40, h: 30 }, bubbles: [], rocks: [], parts: [] };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 0, 320);

    if (input.firePressed && s.bubbles.length < 3) {
      s.bubbles.push({ x: ship.x + 20, y: 580, r: 8, hit: false });
      g.sound("shoot");
    }
    for (const b of s.bubbles) b.y -= 6;

    // grosse Felsbrocken erscheinen von oben
    if (g.frame % (g.level >= 2 ? 40 : 50) === 0) {
      s.rocks.push({ x: g.randInt(28, g.W - 28), y: g.TOP - 20, r: 28, big: true, vx: 0 });
    }
    for (const r of s.rocks) {
      r.y += r.big ? 0.8 : 1.2;
      r.x += r.vx;
    }

    // Treffer Blase gegen Felsbrocken
    const alive = [];
    for (const r of s.rocks) {
      let hit = false;
      for (const b of s.bubbles) {
        if (!b.hit && g.hit({ x: b.x, y: b.y, r: b.r }, { x: r.x, y: r.y, r: r.r })) { b.hit = true; hit = true; break; }
      }
      if (!hit) { alive.push(r); continue; }
      for (let i = 0; i < 6; i++) s.parts.push({ x: r.x + g.randInt(-12, 12), y: r.y + g.randInt(-12, 12), t: 8 });
      if (r.big) {
        alive.push({ x: r.x - 12, y: r.y, r: 14, big: false, vx: -0.5 });
        alive.push({ x: r.x + 12, y: r.y, r: 14, big: false, vx: 0.5 });
        g.addScore(10);
        g.sound("pop");
      } else {
        g.addScore(20);
        g.sound("coin");
      }
    }
    s.rocks = alive.filter((r) => r.y <= g.H);
    s.bubbles = s.bubbles.filter((b) => !b.hit && b.y >= g.TOP);

    // Level alle 100 Punkte
    while (g.score >= g.level * 100) g.nextLevel();

    for (const p of s.parts) p.t -= 1;
    s.parts = s.parts.filter((p) => p.t > 0);

    // Beruehrung mit dem Raumschiff beendet die Runde
    const shipC = { x: ship.x + 20, y: ship.y + 15, r: 16 };
    for (const r of s.rocks) {
      if (g.hit(shipC, { x: r.x, y: r.y, r: r.r })) { g.sound("hurt"); g.loseLife(); return; }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const b of s.bubbles) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const r of s.rocks) d.emoji("🌑", r.x, r.y, r.big ? 60 : 30);
    for (const p of s.parts) d.circle(p.x, p.y, 3, "yellow");
    d.emoji("🚀", s.ship.x + 20, s.ship.y + 15, 36);
  }
};

// Kartenspiel gegen den Computer (Runden-Vorlage). Ablegen und Ziehen laufen ueber Cursor und Feuer, nicht ueber Tippen auf Karten.
const STUFEN = ["leicht", "mittel", "schwer"];
const MUSTER = ["Stern", "Herz", "Kreis", "Apfel"];
const EMO = ["⭐", "💗", null, "🍎"];
const MAX_ZUEGE = 30, WIEDERHOLEN = 12;

export default {
  title: "Kartenspiel gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init() {
    return { phase: "menue", schwierigkeit: "mittel", hand: [], comp: [], stapel: [], ablage: null, turn: "spieler", cur: 0, halten: 0, wait: 0, hinweis: "", hinweisT: 0, zuege: 0, ergebnis: "" };
  },

  update(s, input, g) {
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    let step = false;
    if (dx === 0 && dy === 0) s.halten = 0;
    else if (s.halten <= 0) { step = true; s.halten = WIEDERHOLEN - 1; }
    else s.halten -= 1;
    if (s.hinweisT > 0) { s.hinweisT -= 1; if (s.hinweisT === 0) s.hinweis = ""; }

    if (s.phase === "menue") {
      if (step) { const i = STUFEN.indexOf(s.schwierigkeit); s.schwierigkeit = STUFEN[g.clamp(i + dx + dy, 0, 2)]; }
      if (input.firePressed) start(s, g);
      return;
    }
    if (s.phase !== "spiel") return;

    const n = s.hand.length;
    s.cur = Math.min(s.cur, n);
    if (s.turn === "computer") {
      s.wait -= 1;
      if (s.wait <= 0) computerZug(s, g);
      return;
    }
    if (step) {
      if (dx !== 0) s.cur = g.clamp(s.cur + dx, 0, n);
      if (dy > 0) s.cur = n;
      else if (dy < 0 && s.cur === n) s.cur = Math.max(0, n - 1);
    }
    if (!input.firePressed) return;
    if (s.cur < n) spielKarte(s, g, s.cur);
    else stapelZug(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    if (s.phase === "menue") {
      d.text("Kartenspiel", 180, 150, { size: 32, align: "center" });
      d.text("gegen den Computer", 180, 190, { size: 20, align: "center" });
      d.text("Schwierigkeit", 180, 260, { size: 20, align: "center" });
      STUFEN.forEach((st, i) => d.text(st === s.schwierigkeit ? "> " + st + " <" : st, 180, 300 + i * 40, { size: 24, align: "center" }));
      d.text("Auf/Ab wählt, Feuer startet", 180, 470, { size: 16, align: "center" });
      return;
    }
    if (s.phase === "ende") {
      d.text(s.ergebnis, 180, 300, { size: 44, align: "center" });
      d.text("Züge: " + s.zuege, 180, 360, { size: 20, align: "center" });
      return;
    }
    d.text(s.turn === "spieler" ? "Du bist dran" : "Computer ist dran", 180, 70, { size: 20, align: "center" });
    const cn = s.comp.length;
    for (let i = 0; i < cn; i++) d.rect(rowX(g, cn, 44, 6, i), 100, 44, 60, "yellow", { round: 8, line: true });
    d.rect(70, 236, 64, 92, s.stapel.length > 0 ? "yellow" : "cream", { round: 8, shadow: s.stapel.length > 0, line: true });
    d.text("Stapel: " + s.stapel.length, 102, 345, { size: 16, align: "center" });
    if (s.ablage) drawCard(d, s.ablage, 226, 236, 64, 92);
    if (s.hinweisT > 0) d.text(s.hinweis, 180, 380, { size: 18, align: "center" });
    const hn = s.hand.length;
    for (let i = 0; i < hn; i++) drawCard(d, s.hand[i], rowX(g, hn, 60, 6, i), 440, 60, 88);
    if (s.turn === "spieler") {
      if (s.cur < hn) frame(d, rowX(g, hn, 60, 6, s.cur) - 4, 436, 68, 96);
      else frame(d, 66, 232, 72, 100);
    }
    d.text("Züge: " + s.zuege + " / " + MAX_ZUEGE, 180, 600, { size: 16, align: "center" });
  }
};

function start(s, g) {
  const deck = [];
  for (let m = 0; m < 4; m++) for (let w = 1; w <= 4; w++) deck.push({ m, w });
  for (let i = deck.length - 1; i > 0; i--) { const j = g.randInt(0, i); const t = deck[i]; deck[i] = deck[j]; deck[j] = t; }
  const nimm = (m) => deck.splice(deck.findIndex((c) => c.m === m), 1)[0];
  const rest = () => deck.splice(g.randInt(0, deck.length - 1), 1)[0];
  s.hand = []; s.comp = [];
  for (let m = 0; m < 4; m++) s.hand.push(nimm(m));
  for (let m = 0; m < 4; m++) s.comp.push(nimm(m));
  s.hand.push(rest());
  s.comp.push(rest());
  s.ablage = rest();
  s.stapel = deck;
  s.phase = "spiel"; s.turn = "spieler"; s.cur = 0; s.halten = 0; s.wait = 0;
  s.hinweis = ""; s.hinweisT = 0; s.zuege = 0; s.ergebnis = "";
}

function passt(a, b) { return a.m === b.m || a.w === b.w; }

function spielKarte(s, g, i) {
  const c = s.hand[i];
  if (!passt(c, s.ablage)) { s.hinweis = "Passt nicht"; s.hinweisT = 60; g.sound("hurt"); return; }
  s.hand.splice(i, 1);
  s.ablage = c;
  g.addScore(10);
  g.sound("pop");
  if (s.hand.length === 0) return ende(s, g, true);
  endZug(s, g, "computer");
}

function stapelZug(s, g) {
  if (s.stapel.length === 0) {
    if (s.hand.some((c) => passt(c, s.ablage))) { s.hinweis = "Stapel ist leer"; s.hinweisT = 60; return; }
    s.hinweis = "Keine Karte passt, Zug aussetzen"; s.hinweisT = 60;
    endZug(s, g, "computer");
    return;
  }
  s.hand.push(s.stapel.pop());
  g.addScore(2);
  g.sound("coin");
  s.hinweis = "Du ziehst eine Karte"; s.hinweisT = 60;
  endZug(s, g, "computer");
}

function computerZug(s, g) {
  const idx = [];
  s.comp.forEach((c, i) => { if (passt(c, s.ablage)) idx.push(i); });
  if (idx.length > 0) {
    let pick = idx[0];
    if (s.schwierigkeit === "leicht") pick = idx[g.randInt(0, idx.length - 1)];
    else if (s.schwierigkeit === "schwer") {
      let best = -1;
      for (const i of idx) {
        const k = s.comp.filter((c) => c.m === s.comp[i].m).length;
        if (k > best) { best = k; pick = i; }
      }
    }
    const c = s.comp.splice(pick, 1)[0];
    s.ablage = c;
    s.hinweis = "Computer legt " + MUSTER[c.m] + " " + c.w; s.hinweisT = 60;
    g.sound("pop");
    if (s.comp.length === 0) return ende(s, g, false);
    endZug(s, g, "spieler");
  } else {
    if (s.stapel.length > 0) { s.comp.push(s.stapel.pop()); s.hinweis = "Computer zieht eine Karte"; }
    else s.hinweis = "Computer passt";
    s.hinweisT = 60;
    endZug(s, g, "spieler");
  }
}

function endZug(s, g, next) {
  s.zuege += 1;
  if (s.zuege >= MAX_ZUEGE) return ende(s, g, s.hand.length < s.comp.length);
  s.turn = next;
  s.cur = Math.min(s.cur, s.hand.length);
  if (next === "computer") s.wait = 40;
}

function ende(s, g, sieg) {
  s.phase = "ende";
  s.ergebnis = sieg ? "Sieg!" : "Niederlage";
  if (sieg) g.win(); else g.gameOver();
}

function rowX(g, n, w, gap, i) {
  return (g.W - (n * (w + gap) - gap)) / 2 + i * (w + gap);
}

function frame(d, x, y, w, h) {
  d.rect(x, y, w, 4, "red"); d.rect(x, y + h - 4, w, 4, "red");
  d.rect(x, y, 4, h, "red"); d.rect(x + w - 4, y, 4, h, "red");
}

function drawCard(d, c, x, y, w, h) {
  d.rect(x, y, w, h, "cream", { round: 8, line: true });
  if (c.m === 2) d.circle(x + w / 2, y + h / 2 - 10, 14, "yellow", { line: true });
  else d.emoji(EMO[c.m], x + w / 2, y + h / 2 - 10, 30);
  d.text(String(c.w), x + w / 2, y + h - 18, { size: 18, align: "center", color: "ink" });
}

// Mau Mau gegen den Computer (nur Spiel-API, keine Importe). Runde: 5 Karten je Seite, passende Karte nach Farbe oder Rang.
// Jede Steuerung und jeder Tipp zeigt sofort eine Rueckmeldung (s.msg), damit nichts wirkungslos bleibt.
const RANKS = ["7", "8", "9", "10", "U", "O", "K", "A"];
const SUITS = ["♥", "♦", "♣", "♠"];
const ZUGLIMIT = 30, WARTE = 40, HALTEN = 12;

export default {
  title: "Mau Mau gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const deck = [];
    for (let f = 0; f < 4; f++) for (let r = 0; r < 8; r++) deck.push({ r, f });
    shuffle(deck, g);
    const hand = [], comp = [];
    for (let i = 0; i < 5; i++) { hand.push(deck.pop()); comp.push(deck.pop()); }
    const ablage = deck.pop();
    return { hand, comp, stapel: deck, ablage, cx: 0, zone: 0, halten: 0, phase: "du", warte: 0, zuegeS: 0, zuegeC: 0, ende: "", msg: "", msgT: 0, tasten: 0 };
  },

  update(s, input, g) {
    if (s.msgT > 0) { s.msgT -= 1; if (s.msgT === 0) s.msg = ""; }
    if (s.phase === "comp") {
      s.warte -= 1;
      if (s.warte <= 0) computerZug(s, g);
      return;
    }
    if (input.left || input.right || input.up || input.down) s.tasten += 1;
    if (input.up) s.zone = 1;
    else if (input.down) s.zone = 0;
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    if (dx !== 0 && s.zone === 0) {
      if (s.halten % HALTEN === 0) s.cx = g.clamp(s.cx + dx, 0, s.hand.length - 1);
      s.halten += 1;
    } else s.halten = 0;
    if (!input.firePressed || s.ende) return;
    if (s.zone === 0) spielerKarte(s, g);
    else spielerStapel(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    const n = s.comp.length;
    const sp = Math.min(50, 300 / Math.max(1, n));
    for (let i = 0; i < n; i++) d.rect(20 + i * sp, 90, 46, 64, "ink", { round: 6 });
    d.text("Computer: " + n + " Karten", 20, 70, { size: 16 });

    if (s.zone === 1) d.rect(114, 294, 58, 76, "red", { round: 8 });
    d.rect(120, 300, 46, 64, "yellow", { round: 6, line: true });
    d.text(String(s.stapel.length), 143, 322, { size: 16, align: "center" });
    cardDraw(d, s.ablage, 180, 300);
    d.text(s.phase === "du" ? "Du am Zug" : "Computer am Zug", 180, 250, { size: 18, align: "center" });
    d.text("Züge: du " + s.zuegeS + " / " + ZUGLIMIT + ", Computer " + s.zuegeC, 180, 390, { size: 14, align: "center" });
    if (s.msg) d.text(s.msg, 180, 420, { size: 14, align: "center" });

    const hn = s.hand.length;
    const hsp = Math.min(50, 300 / Math.max(1, hn));
    for (let i = 0; i < hn; i++) {
      const x = 20 + i * hsp;
      if (s.zone === 0 && i === s.cx) d.rect(x - 3, 497, 52, 70, "red", { round: 8 });
      cardDraw(d, s.hand[i], x, 500);
    }
    d.text("Deine Karten", 20, 476, { size: 18 });

    if (s.ende) {
      d.rect(50, 230, 260, 70, "yellow", { round: 10, line: true });
      d.text(s.ende, 180, 262, { size: 20, align: "center" });
    }
  }
};

function shuffle(deck, g) {
  for (let i = deck.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = deck[i];
    deck[i] = deck[j];
    deck[j] = t;
  }
}

function passt(c, a) {
  return c.r === a.r || c.f === a.f;
}

function sag(s, text) {
  s.msg = text;
  s.msgT = 60;
}

function cardDraw(d, c, x, y) {
  const farbe = c.f === 0 || c.f === 1 ? "red" : "ink";
  d.rect(x, y, 46, 64, "cream", { round: 6, line: true });
  d.text(RANKS[c.r], x + 6, y + 8, { size: 14, color: "ink" });
  d.text(SUITS[c.f], x + 23, y + 30, { size: 22, color: farbe, align: "center" });
}

function spielerKarte(s, g) {
  const c = s.hand[s.cx];
  if (!c) return;
  if (!passt(c, s.ablage)) { sag(s, "Passt nicht zur Ablage"); return; }
  s.hand.splice(s.cx, 1);
  s.ablage = c;
  s.zuegeS += 1;
  s.msg = "";
  s.msgT = 0;
  g.addScore(5);
  g.sound("pop");
  if (s.hand.length === 0) {
    s.ende = "Du hast gewonnen";
    g.addScore(20);
    g.sound("win");
    g.win();
    return;
  }
  s.cx = g.clamp(s.cx, 0, s.hand.length - 1);
  if (s.zuegeS >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "comp";
  s.warte = WARTE;
}

function spielerStapel(s, g) {
  if (s.hand.some((c) => passt(c, s.ablage))) { sag(s, "Du hast eine passende Karte"); return; }
  if (s.stapel.length === 0) { sag(s, "Stapel ist leer"); return; }
  s.zuegeS += 1;
  s.hand.push(s.stapel.pop());
  s.msg = "";
  s.msgT = 0;
  g.sound("pop");
  if (s.zuegeS >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "comp";
  s.warte = WARTE;
}

function computerZug(s, g) {
  const idx = [];
  for (let i = 0; i < s.comp.length; i++) if (passt(s.comp[i], s.ablage)) idx.push(i);
  if (idx.length > 0) {
    const i = g.random() < 0.7 ? idx[0] : idx[g.randInt(0, idx.length - 1)];
    s.ablage = s.comp.splice(i, 1)[0];
    s.zuegeC += 1;
    g.sound("pop");
    if (s.comp.length === 0) { s.ende = "Computer hat gewonnen"; g.gameOver(); return; }
  } else {
    if (s.stapel.length > 0) s.comp.push(s.stapel.pop());
    s.zuegeC += 1;
  }
  if (s.zuegeC >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "du";
}

// Pong-Tennis: Schlaeger links (du) gegen Computer-Schlaeger rechts. Ball prallt ab, wer verpasst, gibt einen Punkt ab.
// Zeitlimit: nach 1140 Frames endet die Partie, wer mehr Punkte hat, gewinnt.
const PX = 40, CX = 320, PH = 90, BR = 8, SPEED = 4, ZEIT = 1140;

export default {
  title: "Pong-Tennis gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { py: 320, cy: 320, off: 0, t: 0, bx: 180, by: 320, vx: g.randInt(0, 1) === 0 ? SPEED : -SPEED, vy: g.randInt(-2, 2), me: 0, cpu: 0 };
  },

  update(s, input, g) {
    if (input.up) s.py -= 5;
    if (input.down) s.py += 5;
    s.py = g.clamp(s.py, 60, 600);

    s.t += 1;
    if (s.t % 60 === 0) s.off = g.randInt(-40, 40);
    const step = g.clamp(s.by + s.off - s.cy, -3, 3);
    s.cy = g.clamp(s.cy + step, 60, 600);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by <= 56) { s.by = 56; s.vy = Math.abs(s.vy); }
    if (s.by >= 632) { s.by = 632; s.vy = -Math.abs(s.vy); }

    if (s.vx < 0 && s.bx <= 48 && Math.abs(s.by - s.py) <= 50) {
      s.vx = SPEED; s.bx = 48; g.addScore(1); g.sound("hit");
    } else if (s.vx > 0 && s.bx >= 312 && Math.abs(s.by - s.cy) <= 50) {
      s.vx = -SPEED; s.bx = 312; g.sound("hit");
    }

    if (s.bx < 0) {
      s.cpu += 1; g.sound("hurt"); serve(s, g, SPEED);
    } else if (s.bx > 360) {
      s.me += 1; g.addScore(5); g.sound("coin"); serve(s, g, -SPEED);
    }

    if (s.cpu >= 7) { g.gameOver(); return; }
    if (s.me >= 7) { g.win(); return; }
    if (g.frame >= ZEIT) {
      if (s.me > s.cpu) g.win(); else g.gameOver();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.line(180, 56, 180, 632, "yellow", 2);
    d.text(String(s.me), 150, 28, { size: 24, color: "ink", align: "center" });
    d.text(String(s.cpu), 210, 28, { size: 24, color: "ink", align: "center" });
    d.emoji("🏓", PX, s.py, 40);
    d.emoji("🤖", CX, s.cy, 40);
    d.emoji("🎾", s.bx, s.by, 20);
  }
};

function serve(s, g, vx) {
  s.bx = 180; s.by = 320; s.vx = vx; s.vy = g.randInt(-2, 2);
}

// Tennis gegen den Computer: Echtzeit-Pong. Der Computer steuert links, der Spieler rechts.
// Punkte: jeder Schlag des Spielers gibt 1 Punkt, jeder gewonnene Ballwechsel 5 Punkte.
// Zeitlimit: nach 1190 Frames (ca. 20 s) endet die Partie, wer mehr Ballwechsel gewonnen hat, gewinnt.
export default {
  title: "Tennis gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { bx: 180, by: 340, vx: g.randInt(0, 1) ? 3 : -3, vy: g.randInt(0, 1) ? 2 : -2, serve: 30, py: 280, cpy: 280, comp: 0, mine: 0, rally: 0, off: 0 };
  },

  update(s, input, g) {
    if (g.frame >= 1190) {
      if (s.mine > s.comp) g.win(); else g.gameOver();
      return;
    }
    const top = g.TOP + 4, bottom = g.H - 84;
    s.py = g.clamp(s.py + (input.down ? 5 : 0) - (input.up ? 5 : 0), top, bottom);
    if (s.serve > 0) {
      s.serve -= 1;
      return;
    }
    // Computer: zielt auf den Ball mit Zufallsversatz, Tempo steigt mit den Ballwechseln
    const tempo = Math.min(2.5 + 0.25 * s.rally, 6);
    const diff = s.by + s.off - 40 - s.cpy;
    s.cpy = g.clamp(s.cpy + Math.max(-tempo, Math.min(tempo, diff)), top, bottom);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by < g.TOP + 6) { s.by = g.TOP + 6; s.vy = Math.abs(s.vy); }
    else if (s.by > g.H - 16) { s.by = g.H - 16; s.vy = -Math.abs(s.vy); }

    // Schlag links (Computer)
    if (s.vx < 0 && s.bx - 10 <= 34 && s.bx + 10 >= 20 && s.by + 10 >= s.cpy && s.by - 10 <= s.cpy + 80) {
      s.bx = 44;
      hit(s, g, s.cpy);
    }
    // Schlag rechts (Spieler): jeder Schlag gibt einen Punkt
    if (s.vx > 0 && s.bx + 10 >= 326 && s.bx - 10 <= 340 && s.by + 10 >= s.py && s.by - 10 <= s.py + 80) {
      s.bx = 316;
      hit(s, g, s.py);
      g.addScore(1);
      g.sound("hit");
    }

    // Ballwechsel an den Wand hinter einem Schlaeger
    if (s.bx < 0) {
      s.mine += 1;
      g.addScore(5);
      g.sound("coin");
      if (s.mine >= 11) { g.win(); return; }
      reset(s, g, -1);
      return;
    }
    if (s.bx > g.W) {
      s.comp += 1;
      g.sound("lose");
      if (s.comp >= 11) { g.gameOver(); return; }
      reset(s, g, 1);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(180, 110, 180, 620, "ink", 2);
    d.text(String(s.comp), 150, 90, { size: 28, color: "ink", align: "center" });
    d.text(String(s.mine), 210, 90, { size: 28, color: "red", align: "center" });
    d.emoji("🏓", 27, s.cpy + 40, 40);
    d.emoji("🏓", 333, s.py + 40, 40);
    d.emoji("🎾", s.bx, s.by, 24);
  }
};

function hit(s, g, paddleY) {
  s.vx = s.vx > 0 ? Math.min(7, s.vx + 0.1) : Math.max(-7, s.vx - 0.1);
  s.vx = -s.vx;
  s.vy = g.clamp(s.vy + (s.by - (paddleY + 40)) / 12, -6, 6);
  s.rally += 1;
  const amp = Math.max(2, 12 - s.rally);
  s.off = g.randInt(-amp, amp);
}

function reset(s, g, dir) {
  s.bx = 180;
  s.by = 340;
  s.vx = dir * 4;
  s.vy = g.randInt(0, 1) ? 2 : -2;
  s.serve = 30;
  s.rally = 0;
  s.off = 0;
}

// Ball-Duell gegen den Computer: Pong mit Schlaegern links (du) und rechts (Computer).
export default {
  title: "Ball-Duell gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { py: 330, cy: 330, cs: 3, t: 0, mine: 0, bx: 180, by: 330, vx: 3, vy: 2 };
  },

  update(s, input, g) {
    s.t += 1;
    if (input.up) s.py -= 5;
    if (input.down) s.py += 5;
    s.py = g.clamp(s.py, g.TOP + 30, g.H - 30);

    if (s.t % 120 === 0) s.cs = g.randInt(1, 6);
    if (s.cy < s.by) s.cy += s.cs; else s.cy -= s.cs;
    s.cy = g.clamp(s.cy, g.TOP + 30, g.H - 30);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by <= g.TOP + 7) { s.by = g.TOP + 7; s.vy = Math.abs(s.vy); }
    if (s.by >= g.H - 7) { s.by = g.H - 7; s.vy = -Math.abs(s.vy); }

    const ball = { x: s.bx, y: s.by, r: 7 };
    if (s.vx < 0 && g.hit(ball, { x: 12, y: s.py - 30, w: 36, h: 60 })) bounce(s, g, s.py);
    else if (s.vx > 0 && g.hit(ball, { x: 312, y: s.cy - 30, w: 36, h: 60 })) bounce(s, g, s.cy);

    if (s.bx < 0) {
      g.addScore(1);
      g.sound("lose");
      if (g.score >= 5) { g.gameOver(); return; }
      reset(s, g);
    } else if (s.bx > g.W) {
      s.mine += 1;
      g.sound("coin");
      if (s.mine >= 5) { g.win(); return; }
      reset(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = g.TOP; y < g.H; y += 24) d.rect(178, y, 4, 12, "yellow");
    d.emoji("🏓", 30, s.py, 48);
    d.emoji("🏓", 330, s.cy, 48);
    d.circle(s.bx, s.by, 7, "red");
    d.text("Du: " + s.mine, 16, 30, { size: 20, color: "ink", align: "left" });
    d.text("Computer: " + g.score, g.W - 16, 30, { size: 20, color: "ink", align: "right" });
  }
};

function bounce(s, g, py) {
  s.vx = -s.vx;
  const sp = Math.min(Math.abs(s.vx) + 0.2, 8);
  s.vx = s.vx < 0 ? -sp : sp;
  s.vy = g.clamp((s.by - py) * 0.15, -5, 5);
}

function reset(s, g) {
  s.bx = 180;
  s.by = 330;
  s.vx = g.randInt(0, 1) === 0 ? -3 : 3;
  s.vy = g.randInt(0, 1) === 0 ? -2 : 2;
}

// Raumschiff gegen platzende Felsbrocken (nur Spiel-API, keine Importe).
// Seifenblasen schiessen, grosse Felsbrocken brauchen drei Treffer, kleine einen. Ein Zusammenstoss beendet die Runde.
// Nach links 4 px je Frame, nach rechts 2 px je Frame (Ausgleich, damit ein Hin-und-her ehrlich spuerbar nach links fuehrt).
const SPEED_BASE = 1.5, SPEED_LEVEL = 0.2, COOL = 15, SHOT_SPEED = 6, POP_TIME = 12;

export default {
  title: "Raumschiff gegen platzende Felsbrocken",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { ship: { x: 162, y: 562, w: 36, h: 36 }, rocks: [], shots: [], pops: [], cool: 0, spawn: 30 };
  },

  update(s, input, g) {
    // Level alle 1800 Frames
    if (g.frame > 0 && g.frame % 1800 === 0) { g.nextLevel(); g.sound("level"); }

    // Schiff bewegen
    if (input.left) s.ship.x -= 4;
    if (input.right) s.ship.x += 2;
    s.ship.x = g.clamp(s.ship.x, 4, 320);

    // Schuss mit Abkuehlung (Druck oder gehalten)
    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0) {
      s.shots.push({ x: s.ship.x + 18, y: s.ship.y, r: 8, dead: false });
      s.cool = COOL;
      g.sound("shoot");
    }
    for (const b of s.shots) b.y -= SHOT_SPEED;

    // Felsbrocken spawnen
    s.spawn -= 1;
    if (s.spawn <= 0) {
      const big = g.random() < 0.4;
      const r = big ? 26 : 14;
      s.rocks.push({ x: g.randInt(30, g.W - 30), y: g.TOP + r, r, big, hits: big ? 3 : 1, dead: false });
      s.spawn = g.randInt(60, 90);
    }
    const speed = SPEED_BASE + SPEED_LEVEL * g.level;
    for (const r of s.rocks) r.y += speed;

    // Treffer Blase gegen Felsbrocken (jeder Treffer gibt Zwischenpunkte)
    for (const b of s.shots) {
      for (const r of s.rocks) {
        if (b.dead || r.dead) continue;
        if (g.dist(b, r) < b.r + r.r) {
          b.dead = true;
          r.hits -= 1;
          if (r.hits <= 0) {
            r.dead = true;
            g.addScore(r.big ? 30 : 10);
            s.pops.push({ x: r.x, y: r.y, t: POP_TIME });
            g.sound("pop");
          } else {
            g.addScore(2);
            g.sound("hit");
          }
        }
      }
    }

    // Zusammenstoss Schiff gegen Felsbrocken: Runde endet
    for (const r of s.rocks) {
      if (!r.dead && g.hit(s.ship, r)) { g.gameOver(); return; }
    }

    // Aufraeumen
    s.rocks = s.rocks.filter((r) => !r.dead && r.y - r.r < g.H);
    s.shots = s.shots.filter((b) => !b.dead && b.y >= g.TOP);
    for (const p of s.pops) p.t -= 1;
    s.pops = s.pops.filter((p) => p.t > 0);
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.rocks) d.emoji("🪨", r.x, r.y, r.big ? 52 : 28);
    for (const b of s.shots) d.emoji("🫧", b.x, b.y, 20);
    for (const p of s.pops) d.emoji("✨", p.x, p.y, 30);
    d.emoji("🚀", s.ship.x + 18, s.ship.y + 18, 36);
  }
};

// Seifenblasen-Raumschiff: Blasen platzen Felsen. Ein Felsen am Schiff beendet die Runde.
// Rekord-Anzeige fehlt: Die Spiel-API speichert nichts ueber die Runde hinaus.
const SPARK = ["yellow", "red", "ink"];

export default {
  title: "Seifenblasen-Raumschiff",
  controls: ["left", "right", "fire"],
  lives: 1,

  init() {
    return { ship: { x: 170, y: 580, w: 36, h: 30 }, bubbles: [], rocks: [], sparks: [], cool: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 0, g.W - ship.w);

    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bubbles.length < 4) {
      s.bubbles.push({ x: ship.x + ship.w / 2, y: ship.y - 20, r: 8 });
      s.cool = 10;
      g.sound("shoot");
    }
    for (const b of s.bubbles) b.y -= 6;
    s.bubbles = s.bubbles.filter((b) => b.y >= g.TOP);

    if (g.frame % 45 === 0 || g.random() < 0.01) {
      const r = g.randInt(0, 1) === 0 ? 12 : 22;
      s.rocks.push({ x: g.randInt(20, 340), y: g.TOP - 20, r, dead: false });
    }
    const v = Math.min(4, 1.5 + 0.01 * g.frame);
    for (const r of s.rocks) r.y += v;

    for (const b of s.bubbles) {
      for (const r of s.rocks) {
        if (!r.dead && g.dist(b, r) < b.r + r.r) {
          b.dead = true;
          r.dead = true;
          g.addScore(1);
          g.sound("pop");
          for (let k = 0; k < 8; k++) {
            const a = k * 45;
            s.sparks.push({ x: r.x, y: r.y, dx: g.cos(a) * 2.5, dy: g.sin(a) * 2.5, r: 3, c: SPARK[k % 3], t: 20 });
          }
          break;
        }
      }
    }
    s.bubbles = s.bubbles.filter((b) => !b.dead);
    s.rocks = s.rocks.filter((r) => !r.dead && r.y - r.r <= g.H);

    for (const r of s.rocks) {
      const cx = g.clamp(r.x, ship.x, ship.x + ship.w);
      const cy = g.clamp(r.y, ship.y, ship.y + ship.h);
      const dx = r.x - cx, dy = r.y - cy;
      if (dx * dx + dy * dy < r.r * r.r) {
        g.sound("hurt");
        g.loseLife();
        return;
      }
    }

    for (const sp of s.sparks) { sp.x += sp.dx; sp.y += sp.dy; sp.t -= 1; }
    s.sparks = s.sparks.filter((sp) => sp.t > 0);

    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d) {
    d.clear("cream");
    for (const r of s.rocks) d.emoji("🌑", r.x, r.y, r.r * 2 + 8);
    // Bereite Blase am Bug, solange keine Blase unterwegs ist
    if (s.bubbles.length === 0 && s.cool === 0) d.emoji("🫧", s.ship.x + s.ship.w / 2, s.ship.y - 20, 22);
    for (const b of s.bubbles) d.emoji("🫧", b.x, b.y, 22);
    for (const sp of s.sparks) d.circle(sp.x, sp.y, sp.r, sp.c);
    d.emoji("🚀", s.ship.x + 18, s.ship.y + 15, 36);
  }
};

// Mau Mau gegen den Computer (Runden-Kartenspiel, nur Spiel-API, keine Importe).
const FARBEN = ["🍎", "🍋", "🍀", "🌟"];
const ZIEL = 100, ZUEGE_MAX = 60, ZEIT_MAX = 2400, PAUSE = 120, WARTE = 40;

export default {
  title: "Mau Mau gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const s = { runde: 0, pts: 0, zuege: 0, msg: "", sieger: "", rest: 0, halten: 0, rich: 0, zog: false };
    deal(s, g);
    return s;
  },

  update(s, input, g) {
    // Zeit- und Zuglimit gelten immer, auch ohne Eingabe (Spielende ist sicher erreichbar)
    if (g.frame >= ZEIT_MAX || s.zuege >= ZUEGE_MAX) { g.gameOver(); return; }
    if (s.phase === "ende") {
      if (s.rest > 0) s.rest -= 1;
      else if (input.firePressed) deal(s, g);
      return;
    }
    if (s.phase === "comp") { computerZug(s, g); return; }
    spielerZug(s, input, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Du: " + s.pts + " Punkte", 12, 62, { size: 18, color: "ink" });
    d.text("Runde " + s.runde + " · Züge " + s.zuege + "/" + ZUEGE_MAX, 348, 62, { size: 13, color: "ink", align: "right" });
    d.text("Computer: " + s.comp.length + " Karten", 12, 84, { size: 14, color: "ink" });
    const nc = s.comp.length, spc = Math.min(48, Math.floor(330 / Math.max(1, nc)));
    for (let i = 0; i < nc; i++) d.rect(12 + i * spc, 96, 40, 56, "red", { round: 6, line: true });

    d.rect(90, 200, 70, 80, "red", { round: 8, line: true });
    d.text("Stapel " + s.stack.length, 125, 290, { size: 12, color: "ink", align: "center" });
    const top = s.disc[s.disc.length - 1];
    d.rect(200, 200, 70, 80, "cream", { round: 8, line: true });
    d.text(String(top.w), 214, 216, { size: 18, color: "ink" });
    d.emoji(FARBEN[top.f], 235, 250, 34);
    d.text("Ablage", 235, 290, { size: 12, color: "ink", align: "center" });

    d.text(s.msg, 180, 320, { size: 14, color: "ink", align: "center" });
    if (s.phase === "ende") {
      d.text(s.sieger === "du" ? "Du gewinnst die Runde!" : "Computer gewinnt die Runde.", 180, 360, { size: 20, color: "red", align: "center" });
      d.text("Punkte: " + s.pts, 180, 392, { size: 18, color: "ink", align: "center" });
      if (s.rest === 0) d.text("Feuer: nächste Runde", 180, 420, { size: 14, color: "ink", align: "center" });
    }

    d.text("Deine Karten", 12, 444, { size: 14, color: "ink" });
    const n = s.hand.length, sp = Math.min(56, Math.floor(340 / Math.max(1, n)));
    for (let i = 0; i < n; i++) {
      const c = s.hand[i], x = 12 + i * sp, y = 470;
      d.rect(x, y, 50, 96, "cream", { round: 8, line: true });
      d.text(String(c.w), x + 8, y + 20, { size: 18, color: "ink" });
      d.emoji(FARBEN[c.f], x + 25, y + 60, 28);
    }
    if (n > 0) {
      const x = 12 + s.cur * sp, y = 470;
      d.rect(x - 3, y - 3, 56, 3, "red"); d.rect(x - 3, y + 96, 56, 3, "red");
      d.rect(x - 3, y - 3, 3, 102, "red"); d.rect(x + 50, y - 3, 3, 102, "red");
    }
    d.text("Links/Rechts wählen · Feuer legt ab · Hoch/Runter zieht", 180, 600, { size: 11, color: "ink", align: "center" });
  }
};

function passt(a, b) {
  return a.f === b.f || a.w === b.w;
}

function shuffle(list, g) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = list[i]; list[i] = list[j]; list[j] = t;
  }
}

function deal(s, g) {
  const deck = [];
  for (let f = 0; f < 4; f++) for (let w = 1; w <= 7; w++) deck.push({ f, w });
  shuffle(deck, g);
  s.hand = deck.splice(0, 5);
  s.comp = deck.splice(0, 5);
  s.disc = [deck.pop()];
  s.stack = deck;
  s.runde += 1;
  s.cur = 0; s.halten = 0; s.rich = 0; s.zog = false; s.wait = 0;
  s.phase = "du";
  s.rest = 0; s.sieger = "";
  s.msg = "Lege eine passende Karte ab oder zieh.";
}

function ziehen(s, g, wer) {
  if (s.stack.length === 0 && s.disc.length > 1) {
    const alt = s.disc;
    const top = alt.pop();
    s.stack = alt;
    s.disc = [top];
    shuffle(s.stack, g);
  }
  if (s.stack.length === 0) return;
  const c = s.stack.pop();
  if (wer === "du") s.hand.push(c); else s.comp.push(c);
}

function pruefe(s, g) {
  if (s.pts >= ZIEL) g.win();
  else if (s.zuege >= ZUEGE_MAX) g.gameOver();
}

function ende(s, g, wer) {
  s.phase = "ende";
  s.sieger = wer;
  s.rest = PAUSE;
  if (wer === "du") { s.pts += 20; g.addScore(20); g.sound("win"); }
  else g.sound("lose");
  pruefe(s, g);
}

function spielerZug(s, input, g) {
  const n = s.hand.length;
  const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  if (dir !== 0) {
    if (dir !== s.rich || s.halten >= 12) { s.cur = g.clamp(s.cur + dir, 0, Math.max(0, n - 1)); s.halten = 0; }
    s.halten += 1;
  } else s.halten = 0;
  s.rich = dir;

  const top = s.disc[s.disc.length - 1];
  if (input.firePressed) {
    const c = s.hand[s.cur];
    if (c && passt(c, top)) {
      s.hand.splice(s.cur, 1);
      s.disc.push(c);
      s.pts += 5; g.addScore(5); g.sound("pop");
      s.msg = "Gut gelegt! Computer ist am Zug.";
      s.cur = g.clamp(s.cur, 0, Math.max(0, s.hand.length - 1));
      s.zuege += 1;
      if (s.hand.length === 0) ende(s, g, "du");
      else { s.phase = "comp"; s.wait = 0; pruefe(s, g); }
      return;
    }
    s.msg = "Passt nicht: gleiche Farbe oder Wert nötig.";
  }

  if ((input.up || input.down) && !s.zog) {
    if (s.hand.some((c) => passt(c, top))) {
      s.msg = "Du hast eine passende Karte, also nicht ziehen.";
    } else {
      ziehen(s, g, "du");
      s.msg = "Du ziehst eine Karte. Computer ist am Zug.";
      s.zuege += 1;
      s.phase = "comp"; s.wait = 0;
      pruefe(s, g);
    }
  }
  s.zog = !!(input.up || input.down);
}

function computerZug(s, g) {
  s.wait += 1;
  if (s.wait < WARTE) return;
  const top = s.disc[s.disc.length - 1];
  const idx = [];
  for (let i = 0; i < s.comp.length; i++) if (passt(s.comp[i], top)) idx.push(i);
  if (idx.length > 0) {
    const i = g.random() < 0.7 ? idx[0] : idx[g.randInt(0, idx.length - 1)];
    s.disc.push(s.comp.splice(i, 1)[0]);
    g.addScore(1); g.sound("pop");
    s.msg = "Computer legt eine Karte ab.";
    s.zuege += 1;
    if (s.comp.length === 0) { ende(s, g, "comp"); return; }
  } else {
    ziehen(s, g, "comp");
    g.addScore(1);
    s.msg = "Computer zieht eine Karte.";
    s.zuege += 1;
  }
  s.phase = "du"; s.wait = 0;
  pruefe(s, g);
}
